import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, length, sub, add, mul, max, step, mix, color, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @typedef {Object} NodeContext
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry } = ctx.THREE;

  const cleanupTasks = [];

  // Root group
  const root = new Group();
  root.position.set(0, 0.2, 0); // start offset for mount animation
  root.userData.handlers = {};

  // ---------- PANEL ----------
  const PANEL_WIDTH = 3.2;
  const PANEL_HEIGHT = 2.2;
  const panelGeom = new PlaneGeometry(PANEL_WIDTH, PANEL_HEIGHT);

  // Gradient background
  const uvNode = uv();

  const radialGrad = mix(
    color('#14141a'),
    color('#0b0b10'),
    length(sub(uvNode, vec2(0.5)))
  );

  // Grid (0.25 unit pitch)
  const pitch = uniform(0.25);
  const panelSize = vec2(PANEL_WIDTH, PANEL_HEIGHT);
  const worldPos = mul(uvNode, panelSize);
  const gridX = step(fract(div(worldPos.x, pitch)), uniform(0.006 / PANEL_WIDTH));
  const gridY = step(fract(div(worldPos.y, pitch)), uniform(0.006 / PANEL_HEIGHT));
  const gridMask = max(gridX, gridY);
  const gridColor = vec4(color('#e8ecf2'), 0.06);
  const withGrid = mix(radialGrad, gridColor, gridMask);

  // Border (0.006 unit)
  const borderW = uniform(0.006 / PANEL_WIDTH);
  const borderH = uniform(0.006 / PANEL_HEIGHT);
  const borderMaskX = max(step(uvNode.x, borderW), step(1.0 - uvNode.x, borderW));
  const borderMaskY = max(step(uvNode.y, borderH), step(1.0 - uvNode.y, borderH));
  const borderMask = max(borderMaskX, borderMaskY);
  const borderColor = vec4(color('#26262f'), 1.0);
  const finalColor = mix(withGrid, borderColor, borderMask);

  const panelMat = new MeshBasicNodeMaterial();
  panelMat.colorNode = finalColor;
  panelMat.transparent = true;
  panelMat.depthWrite = false;
  panelMat.side = ctx.THREE.DoubleSide;

  const panelMesh = new Mesh(panelGeom, panelMat);
  root.add(panelMesh);
  cleanupTasks.push(() => {
    panelGeom.dispose();
    panelMat.dispose();
  });

  // ---------- GHOST PREVIEW ----------
  const ghostGroup = new Group();
  ghostGroup.position.set(-0.85, 0, 0.01);
  root.add(ghostGroup);

  const ghostOpacityStart = 0.24;
  const ghostOpacityPeak = 0.34;
  const ghostStrokeColor = '#e8ecf2';
  const ghostStrokeOpacityLow = 0.30;
  const ghostBarOpacityLow = 0.22;

  // Wireframe rectangle (ghost card outline)
  const ghostGeom = new PlaneGeometry(1.1, 1.4);
  const ghostMat = new MeshBasicNodeMaterial();
  ghostMat.colorNode = vec4(color(ghostStrokeColor), ghostStrokeOpacityLow);
  ghostMat.transparent = true;
  ghostMat.depthWrite = false;
  const ghostMesh = new Mesh(ghostGeom, ghostMat);
  ghostGroup.add(ghostMesh);

  // Ghost dial circle
  const dialGeom = new CircleGeometry(0.55 / 2, 32);
  const dialMat = new MeshBasicNodeMaterial();
  dialMat.colorNode = vec4(color(ghostStrokeColor), ghostStrokeOpacityLow);
  dialMat.transparent = true;
  dialMat.depthWrite = false;
  const dialMesh = new Mesh(dialGeom, dialMat);
  dialMesh.position.set(0, 0, 0.01);
  ghostGroup.add(dialMesh);

  // Ghost text bars
  const barGeom = new PlaneGeometry(0.7, 0.06);
  const barMat = new MeshBasicNodeMaterial();
  barMat.colorNode = vec4(color(ghostStrokeColor), ghostBarOpacityLow);
  barMat.transparent = true;
  barMat.depthWrite = false;
  const bar1 = new Mesh(barGeom, barMat);
  const bar2 = bar1.clone();
  bar1.position.set(0, -0.45, 0.01);
  bar2.position.set(0, 0.45, 0.01);
  ghostGroup.add(bar1, bar2);

  // Ghost breathing animation (opacity yoyo)
  const ghostMats = [ghostMat, dialMat, barMat];
  ghostMats.forEach((mat) => {
    mat.opacity = ghostOpacityStart;
    const tl = gsap.timeline({ repeat: -1, yoyo: true });
    tl.to(
      mat,
      {
        opacity: ghostOpacityPeak,
        duration: 2.4,
        ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
      },
    ).to(
      mat,
      {
        opacity: ghostOpacityStart,
        duration: 2.4,
        ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
      },
    );
    cleanupTasks.push(() => tl.kill());
  });

  // ---------- TEXT ----------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const padding = 0.5; // column padding
  const columnX = -0.85 + 0.55 + padding; // start right of ghost

  let cursorY = PANEL_HEIGHT / 2 - padding; // start from top edge downwards

  items.forEach((item) => {
    const role = item.role ?? 'body';
    let fontSize = 13;
    let fontWeight = 400;
    let letterSpacing = 0;
    let lineHeight = 1.5;
    let colorHex = '#e8ecf2';

    if (role === 'headline') {
      fontSize = 34;
      fontWeight = 600;
      letterSpacing = -0.01;
      lineHeight = 1.15;
    } else if (role === 'cta-label') {
      fontSize = 13;
      fontWeight = 700;
      letterSpacing = 0.08;
      lineHeight = 1;
    }

    const txt = ctx.fontAtlas.createText(item.text ?? item.content ?? '', {
      fontSize,
      color: colorHex,
      align: 'left',
    });

    txt.position.set(columnX, cursorY - fontSize * 0.01, 0.01);
    root.add(txt);

    // advance cursor
    const lineAdv = fontSize * lineHeight * 0.01;
    cursorY -= lineAdv;
    cleanupTasks.push(() => {
      if (txt.parent) txt.parent.remove(txt);
    });
  });

  // ---------- CTA BUTTON ----------
  const ctaWidth = 1.5;
  const ctaHeight = 0.36;
  const ctaGeom = new PlaneGeometry(ctaWidth, ctaHeight);
  const ctaMat = new MeshStandardNodeMaterial();
  const ctaUV = uv();
  const ctaGradient = mix(
    color('#ff4450'),
    color('#c1121f'),
    ctaUV.y,
  );
  ctaMat.colorNode = ctaGradient;
  ctaMat.emissiveNode = color('#ff2a38');
  ctaMat.emissiveIntensity = 1.5;
  ctaMat.transparent = true;
  ctaMat.depthWrite = false;

  const ctaMesh = new Mesh(ctaGeom, ctaMat);
  const ctaGroup = new Group();
  ctaGroup.add(ctaMesh);
  ctaGroup.position.set(0, -PANEL_HEIGHT / 2 + padding + ctaHeight / 2, 0.02);
  root.add(ctaGroup);
  cleanupTasks.push(() => {
    ctaGeom.dispose();
    ctaMat.dispose();
  });

  // CTA label
  const ctaLabel = ctx.fontAtlas.createText(
    (items.find((i) => i.role === 'cta-label')?.text) ?? '',
    {
      fontSize: 13,
      color: '#16161d',
      align: 'center',
    },
  );
  ctaLabel.position.set(0, 0, 0.01);
  ctaGroup.add(ctaLabel);
  cleanupTasks.push(() => {
    if (ctaLabel.parent) ctaLabel.parent.remove(ctaLabel);
  });

  // CTA press interaction
  root.userData.handlers.press = () => {
    const tl = gsap.timeline();
    tl.to(
      ctaGroup.scale,
      {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      },
    ).to(
      ctaGroup.scale,
      {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.18,
        ease: 'power2.out',
      },
    );
    cleanupTasks.push(() => tl.kill());
  };

  // ---------- MOUNT ANIMATION ----------
  const allMaterials = [
    panelMat,
    ghostMat,
    dialMat,
    barMat,
    ctaMat,
    ...root.traverse((obj) => {
      if (obj.isMesh && obj.material && obj.material.transparent !== undefined) {
        obj.material.opacity = 0;
        obj.material.transparent = true;
      }
    }),
  ];
  const mountTL = gsap.timeline();
  mountTL
    .to(
      root.position,
      {
        y: 0,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
    )
    .to(
      allMaterials,
      {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      '<',
    );
  cleanupTasks.push(() => mountTL.kill());

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    cleanupTasks.forEach((fn) => fn());
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      }
    });
  };

  return root;
}
